"""Scratch rehearsal driver -- not part of the product. Deleted after use."""
from __future__ import annotations

import json
import sys
import time
import urllib.error
import urllib.request

from auditlog.http_transport import LoopbackAuditServer
from auditlog.overlap_planning import (
    OVERLAP_MERGE_LEASE_NAME,
    LeaseNotHeldError,
    WindowSpan,
    execute_overlap_plan,
)
from auditlog.sqlite_storage import SqliteAuditService

TOKEN = "rehearsal-token-9f3a"

BASE_AT = "2026-08-12T14:05:00+00:00"
NEXT_AT = "2026-08-12T14:05:01+00:00"
BASE_PAYLOAD = {"role": "editor", "target": "user:kai"}
DIFF_PAYLOAD = {"role": "viewer", "target": "user:kai"}

ENTRIES = [
    ("mina_copy_1", {"actor": "operator:mina", "action": "role.grant", "outcome": "allowed", "payload": BASE_PAYLOAD, "recorded_at": BASE_AT}),
    ("mina_copy_2", {"actor": "operator:mina", "action": "role.grant", "outcome": "allowed", "payload": BASE_PAYLOAD, "recorded_at": BASE_AT}),
    ("mina_diff_outcome", {"actor": "operator:mina", "action": "role.grant", "outcome": "denied", "payload": BASE_PAYLOAD, "recorded_at": BASE_AT}),
    ("mina_diff_payload", {"actor": "operator:mina", "action": "role.grant", "outcome": "allowed", "payload": DIFF_PAYLOAD, "recorded_at": BASE_AT}),
    ("mina_next_second", {"actor": "operator:mina", "action": "role.grant", "outcome": "allowed", "payload": BASE_PAYLOAD, "recorded_at": NEXT_AT}),
    ("sven_control", {"actor": "operator:sven", "action": "role.grant", "outcome": "allowed", "payload": BASE_PAYLOAD, "recorded_at": BASE_AT}),
]


def _request(url, *, method="GET", token=None, body=None):
    headers = {}
    if token is not None:
        headers["Authorization"] = f"Bearer {token}"
    if body is not None:
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=body, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req) as resp:
            raw = resp.read()
            return resp.status, (json.loads(raw) if raw else None)
    except urllib.error.HTTPError as exc:
        with exc:
            raw = exc.read()
        return exc.code, (json.loads(raw) if raw else None)


def mode_record_http(db_path: str) -> None:
    service = SqliteAuditService(db_path)
    server = LoopbackAuditServer(service, TOKEN)
    server.start()
    try:
        created = {}
        for label, entry in ENTRIES:
            body = json.dumps(entry).encode("utf-8")
            status, resp = _request(f"{server.base_url}/v1/entries", method="POST", token=TOKEN, body=body)
            created[label] = {"status": status, "public_fields": resp, "receipt_leaked": bool(resp and ("stored_receipt" in resp or "receipt" in resp))}

        status, all_rows = _request(f"{server.base_url}/v1/entries", token=TOKEN)
        status_mina, mina_rows = _request(f"{server.base_url}/v1/entries?actor=operator:mina", token=TOKEN)
        status_sven, sven_rows = _request(f"{server.base_url}/v1/entries?actor=operator:sven", token=TOKEN)

        print(json.dumps({
            "created": created,
            "query_all_status": status,
            "query_all_rows": all_rows,
            "query_mina_count": len(mina_rows) if mina_rows else 0,
            "query_sven_count": len(sven_rows) if sven_rows else 0,
        }))
    finally:
        server.stop()


def mode_acquire_lease(db_path: str, owner: str, ttl_seconds: str) -> None:
    service = SqliteAuditService(db_path)
    acquired = service.acquire_worker_lease(OVERLAP_MERGE_LEASE_NAME, owner, ttl_seconds=float(ttl_seconds))
    lease = service.current_worker_lease(OVERLAP_MERGE_LEASE_NAME)
    print(json.dumps({
        "acquired": acquired,
        "lease_owner": lease.owner if lease else None,
        "lease_expires_at": lease.expires_at if lease else None,
        "now": time.time(),
    }))


def mode_resume_execute(db_path: str, owner: str) -> None:
    service = SqliteAuditService(db_path)
    lease_before = service.current_worker_lease(OVERLAP_MERGE_LEASE_NAME)

    spans = [
        WindowSpan(label="red", source="archive", range_start=BASE_AT, range_end=NEXT_AT),
        WindowSpan(label="blue", source="archive", range_start=BASE_AT, range_end=NEXT_AT),
    ]

    before_copies = service.all_copies()
    before_count = len(before_copies)

    result = {
        "lease_owner_before": lease_before.owner if lease_before else None,
        "lease_expires_at_before": lease_before.expires_at if lease_before else None,
        "now_at_resume": time.time(),
        "copies_before_execute": before_count,
    }

    try:
        plan = execute_overlap_plan(service, spans, owner=owner, ttl_seconds=60.0)
        result["lease_not_held_error"] = None
        result["window_pairs"] = list(plan.window_pairs)
        result["groups"] = [
            {
                "repair_key": g.repair_key,
                "basis": g.basis,
                "member_sequences": list(g.member_sequences),
                "window_labels": list(g.window_labels),
            }
            for g in plan.groups
        ]
    except LeaseNotHeldError as exc:
        result["lease_not_held_error"] = str(exc)
        result["window_pairs"] = None
        result["groups"] = None

    after_copies = service.all_copies()
    result["copies_after_execute"] = len(after_copies)
    result["sequences_after_execute"] = [row.sequence for row in after_copies]

    lease_after = service.current_worker_lease(OVERLAP_MERGE_LEASE_NAME)
    result["lease_owner_after"] = lease_after.owner if lease_after else None

    print(json.dumps(result))


def mode_read_durable(db_path: str) -> None:
    service = SqliteAuditService(db_path)
    copies = service.all_copies()
    rows = [
        {
            "sequence": row.sequence,
            "actor": row.event.actor,
            "action": row.event.action,
            "outcome": row.event.outcome,
            "recorded_at": row.event.recorded_at,
            "content_id": row.event.content_id,
            "source": row.source,
            "has_stored_receipt": row.stored_receipt is not None,
        }
        for row in copies
    ]
    groups = service.stored_overlap_plan_groups()
    stored_groups = [
        {
            "repair_key": g.repair_key,
            "basis": g.basis,
            "member_sequences": list(g.member_sequences),
            "window_labels": list(g.window_labels),
        }
        for g in groups
    ]
    lease = service.current_worker_lease(OVERLAP_MERGE_LEASE_NAME)
    print(json.dumps({
        "copies": rows,
        "distinct_content_ids": sorted({row["content_id"] for row in rows}),
        "stored_overlap_plan_groups": stored_groups,
        "lease_owner": lease.owner if lease else None,
    }))


def main() -> None:
    mode = sys.argv[1]
    if mode == "record_http":
        mode_record_http(sys.argv[2])
    elif mode == "acquire_lease":
        mode_acquire_lease(sys.argv[2], sys.argv[3], sys.argv[4])
    elif mode == "resume_execute":
        mode_resume_execute(sys.argv[2], sys.argv[3])
    elif mode == "read_durable":
        mode_read_durable(sys.argv[2])
    else:
        raise SystemExit(f"unknown mode {mode!r}")


if __name__ == "__main__":
    main()

