def all_events_with_repair_keys(
    self,
    *,
    http_compatibility_validator: Callable[..., str | None] = verified_http_compatibility_key,
) -> list[RepairedRow]:
    """Pair rows with validated archive candidates while preserving lineage."""
    import hashlib
    import hmac
    from datetime import datetime, timezone

    prepared: list[tuple[CopyObservation, str | None, str, str]] = []
    for row in self.all_copies():
        complete = complete_event_identity(row.event.recorded_at, row.event.content_id)
        candidate = None
        basis = BASIS_VERIFIED_HTTP_COMPATIBILITY
        if row.verified_lineage is not None:
            candidate, basis = row.verified_lineage, BASIS_VERIFIED_LINEAGE
        elif row.source == "http" and row.stored_receipt is not None:
            prefix = "http-archive-ms-v1:"
            fields = row.stored_receipt[len(prefix):].split(":", 1) if row.stored_receipt.startswith(prefix) else []
            timestamp = row.event.recorded_at[:-1] + "+00:00" if row.event.recorded_at.endswith("Z") else row.event.recorded_at
            try:
                parsed = datetime.fromisoformat(timestamp)
            except ValueError:
                parsed = None
            if parsed is not None and parsed.tzinfo is not None and parsed.microsecond % 1000 != 0 and len(fields) == 2:
                archive_digest, exact_receipt = fields
                valid_shape = len(archive_digest) == 64 and archive_digest == archive_digest.lower() and all(c in "0123456789abcdef" for c in archive_digest)
                validated = http_compatibility_validator(exact_receipt, row.event.actor, row.event.action, row.event.outcome, row.event.payload, row.event.recorded_at, row.event.content_id, row.source, row.verified_lineage)
                archive_time = parsed.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")
                canonical = json.dumps({"actor": row.event.actor, "action": row.event.action, "outcome": row.event.outcome, "payload": dict(row.event.payload), "recorded_at": archive_time}, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False)
                expected_digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
                if valid_shape and validated == complete and hmac.compare_digest(archive_digest, expected_digest):
                    candidate = f"http-archive-ms-v1:{archive_digest}"
        if candidate is None and row.verified_lineage is None:
            candidate = http_compatibility_validator(row.stored_receipt, row.event.actor, row.event.action, row.event.outcome, row.event.payload, row.event.recorded_at, row.event.content_id, row.source, row.verified_lineage)
        prepared.append((row, candidate, basis, complete))
    identities: dict[str, set[str]] = {}
    for _, candidate, _, complete in prepared:
        if candidate is not None:
            identities.setdefault(candidate, set()).add(complete)
    valid = {candidate for candidate, values in identities.items() if len(values) >= 2}
    return [
        RepairedRow(copy_observation=row, repair_key=candidate, basis=basis)
        if candidate is not None and candidate in valid
        else RepairedRow(copy_observation=row, repair_key=complete, basis=BASIS_COMPLETE_IDENTITY)
        for row, candidate, basis, complete in prepared
    ]

